import{_ as t}from"./chunks/visibility_progress.hOO4BvNJ.js";import{_ as i,c as r,o as a,ae as o}from"./chunks/framework.CliRSA9F.js";const y=JSON.parse('{"title":"Visibility Progress","description":"","frontmatter":{},"headers":[],"relativePath":"features/visibility-progress.md","filePath":"features/visibility-progress.md"}'),s={name:"features/visibility-progress.md"};function n(l,e,c,h,d,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="visibility-progress" tabindex="-1">Visibility Progress <a class="header-anchor" href="#visibility-progress" aria-label="Permalink to &quot;Visibility Progress&quot;">​</a></h1><h2 id="understand-your-podcast-s-overall-visibility-score" tabindex="-1">Understand Your Podcast&#39;s Overall Visibility Score <a class="header-anchor" href="#understand-your-podcast-s-overall-visibility-score" aria-label="Permalink to &quot;Understand Your Podcast&#39;s Overall Visibility Score&quot;">​</a></h2><p>Visibility Progress breaks down how PodSEO calculates your podcast&#39;s visibility rank. See the components that contribute to your score — chart rankings, editorial features, and search performance — with historical trends for each.</p><p><strong>To access</strong>: Navigate to <strong>Traction</strong> in the sidebar, then select <strong>Visibility Progress</strong>.</p><p><img src="'+t+'" alt="Visibility Progress Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="your-visibility-score" tabindex="-1"><strong>Your Visibility Score</strong> <a class="header-anchor" href="#your-visibility-score" aria-label="Permalink to &quot;**Your Visibility Score**&quot;">​</a></h2><p>The hero of the page is your <strong>Visibility Score</strong> — a large number summarizing how discoverable your podcast is across platforms. Next to it, a badge shows where you stand among all indexed podcasts: a <strong>Top X%</strong> badge once your placement is known, or <strong>Rank pending</strong> while there isn&#39;t yet enough data to place you. When a notable change occurs, a short summary explains what moved your score that period.</p><p>Below the score is a trend chart with a <strong>Daily / Weekly</strong> toggle. The weekly view is shown by default and is the best way to read your overall direction over the past month; flip the toggle to <strong>Daily</strong> when you want to see day-by-day movement in finer detail.</p><h2 id="contributing-factors" tabindex="-1"><strong>Contributing Factors</strong> <a class="header-anchor" href="#contributing-factors" aria-label="Permalink to &quot;**Contributing Factors**&quot;">​</a></h2><p>Your visibility comes from three contributing factors, each shown as its own card with a current score, a sparkline trend, and a link to the full feature behind it:</p><h3 id="charts" tabindex="-1"><strong>Charts</strong> <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;**Charts**&quot;">​</a></h3><p>Points earned from your positions in platform top charts across countries and categories. Higher chart positions and more chart appearances increase this factor. The card links to <a href="/features/my-charts.html">My Charts</a>.</p><h3 id="editorial" tabindex="-1"><strong>Editorial</strong> <a class="header-anchor" href="#editorial" aria-label="Permalink to &quot;**Editorial**&quot;">​</a></h3><p>Points earned from appearances in curated editorial lists and featured sections. Both current placements and recent history contribute. The card links to <a href="/features/my-placements.html">Editorial Presence</a>.</p><h3 id="search" tabindex="-1"><strong>Search</strong> <a class="header-anchor" href="#search" aria-label="Permalink to &quot;**Search**&quot;">​</a></h3><p>Points earned from how well your podcast ranks in search results for relevant keywords across platforms. Strong keyword rankings raise this factor. The card links to <a href="/features/show-visibility.html">Show Visibility</a>.</p><h2 id="how-scoring-works" tabindex="-1"><strong>How Scoring Works</strong> <a class="header-anchor" href="#how-scoring-works" aria-label="Permalink to &quot;**How Scoring Works**&quot;">​</a></h2><p>A collapsible <strong>How scoring works</strong> section lays out the simple relationship behind your score:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Charts + Editorial + Search → Visibility Score → Rank</span></span></code></pre></div><p>In other words, your three contributing factors combine into your Visibility Score, which in turn determines your Rank.</p><h3 id="score-modifiers" tabindex="-1"><strong>Score Modifiers</strong> <a class="header-anchor" href="#score-modifiers" aria-label="Permalink to &quot;**Score Modifiers**&quot;">​</a></h3><p>The same section also explains the <strong>score modifiers</strong> — signals that can raise your score when they&#39;re strong or lower it when they&#39;re missing:</p><ul><li><strong>Content Optimization</strong> — How well your titles, descriptions, and metadata are optimized for discovery</li><li><strong>Episode Recency</strong> — Recent episodes signal an active podcast</li><li><strong>Consistency</strong> — A regular publishing schedule shows reliability</li></ul><h2 id="activity-and-signals" tabindex="-1"><strong>Activity and Signals</strong> <a class="header-anchor" href="#activity-and-signals" aria-label="Permalink to &quot;**Activity and Signals**&quot;">​</a></h2><p>Below the score and contributing factors is the <strong>Activity and Signals</strong> timeline — a week-by-week view of what actually happened over the past thirty days. Each entry is labeled by week and shows the change in your Visibility Score for that week (up, down, or flat), so you can connect movement in your score to the events behind it.</p><p>Within each week you&#39;ll see two kinds of entries:</p><ul><li><strong>Actions</strong> — things you did that affect visibility, such as publishing episodes or updating metadata</li><li><strong>Signals</strong> — notable changes PodSEO detected, such as new chart positions, editorial placements, or keyword movement</li></ul><p>Weeks with nothing recorded are clearly marked, so a quiet week reads as quiet rather than missing. This timeline is the most useful part of the page for understanding <em>why</em> your score moved — instead of guessing, you can scroll back through the weeks and see the specific actions and signals that landed each time.</p><h2 id="using-visibility-progress-strategically" tabindex="-1"><strong>Using Visibility Progress Strategically</strong> <a class="header-anchor" href="#using-visibility-progress-strategically" aria-label="Permalink to &quot;**Using Visibility Progress Strategically**&quot;">​</a></h2><h3 id="identifying-strengths-and-weaknesses" tabindex="-1"><strong>Identifying Strengths and Weaknesses</strong> <a class="header-anchor" href="#identifying-strengths-and-weaknesses" aria-label="Permalink to &quot;**Identifying Strengths and Weaknesses**&quot;">​</a></h3><p>Look at each component to understand where your visibility comes from:</p><ul><li><strong>Strong chart score, weak search</strong> — Your content performs well but may need SEO optimization</li><li><strong>Strong search, weak editorial</strong> — Consider pursuing editorial features more actively</li><li><strong>Balanced scores</strong> — Good overall visibility from multiple sources</li></ul><h3 id="tracking-progress" tabindex="-1"><strong>Tracking Progress</strong> <a class="header-anchor" href="#tracking-progress" aria-label="Permalink to &quot;**Tracking Progress**&quot;">​</a></h3><p>The contributing-factor sparklines reveal trends:</p><ul><li><strong>Rising trends</strong> — Your efforts in that area are working</li><li><strong>Declining trends</strong> — May need attention or investigation</li><li><strong>Stable trends</strong> — Consistent performance, consider pushing for growth</li></ul><h3 id="prioritizing-efforts" tabindex="-1"><strong>Prioritizing Efforts</strong> <a class="header-anchor" href="#prioritizing-efforts" aria-label="Permalink to &quot;**Prioritizing Efforts**&quot;">​</a></h3><p>Use the breakdown to focus your optimization:</p><ul><li><strong>Biggest gap</strong> — The component with the most room for improvement</li><li><strong>Easiest wins</strong> — Areas where small improvements could boost your score</li><li><strong>Maintaining strengths</strong> — Don&#39;t neglect what&#39;s already working</li></ul><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><p>Each contributing-factor card links to its detailed feature:</p><ul><li><strong>Charts</strong> → <a href="/features/my-charts.html">My Charts</a> for detailed chart positions</li><li><strong>Editorial</strong> → <a href="/features/my-placements.html">Editorial Presence</a> for editorial tracking</li><li><strong>Search</strong> → <a href="/features/show-visibility.html">Show Visibility</a> for organic keyword rankings</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>Visibility Progress is available to paid plan users. Your score, contributing factors, and timeline data appear once they&#39;re available.</p><p>For a deeper explanation of how the score and rank are calculated, including component weights and common questions, see <a href="/getting-started/visibility-score-explained.html">Visibility Score Explained</a>.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Check Visibility Progress monthly to track long-term trends rather than daily fluctuations</li><li>Focus on your weakest component for the biggest potential improvement</li><li>Click a contributing-factor card to dive into the specific area that needs attention</li><li>A declining trend in one area doesn&#39;t always mean something is wrong — seasonal factors and competitive changes can affect scores</li></ul><p>Visibility Progress gives you a clear picture of what&#39;s driving your podcast&#39;s discoverability, helping you focus your optimization efforts where they&#39;ll have the greatest impact.</p>',48)])])}const b=i(s,[["render",n]]);export{y as __pageData,b as default};
